effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
bool u_xlatb1;
vec4 u_xlat2;
bvec4 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec4 u_xlat6;
vec3 u_xlat8;
bool u_xlatb8;
float u_xlat10;
bool u_xlatb10;
vec2 u_xlat15;
float u_xlat17;
float u_xlat22;
bool u_xlatb24;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = _angle * 0.0174532998;
    u_xlat8.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat8.xy = u_xlat8.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat2.x = cos(u_xlat1.x);
    u_xlat1.x = sin(u_xlat1.x);
    u_xlat3.x = (-u_xlat2.x);
    u_xlat3.y = u_xlat1.x;
    u_xlat3.z = u_xlat2.x;
    u_xlat2.x = dot(u_xlat8.xy, u_xlat3.yz);
    u_xlat2.y = dot(u_xlat8.xy, u_xlat3.xy);
    u_xlat1.xy = u_xlat2.xy / vec2(_scale);
    u_xlat15.xy = u_xlat1.xy + (-vec2(vec2(_offset1, _offset1)));
    u_xlat1.xy = u_xlat1.xy + vec2(_offset2.y, _offset2.x);
    u_xlat1.xy = (int(_type) != 0) ? u_xlat1.xy : u_xlat15.xy;
    u_xlat15.x = u_xlat1.x + 0.5;
    u_xlat22 = dot(u_xlat1.xy, u_xlat1.xy);
    u_xlat22 = sqrt(u_xlat22);
    u_xlat22 = u_xlat22 + u_xlat22;
    u_xlatb2 = equal(ivec4(int(_type), int(_type), int(_blend_mode), int(_blend_mode)), ivec4(1, 2, 1, 2));
    u_xlat3.x = min(abs(u_xlat1.y), abs(u_xlat1.x));
    u_xlat10 = max(abs(u_xlat1.y), abs(u_xlat1.x));
    u_xlat10 = float(1.0) / u_xlat10;
    u_xlat3.x = u_xlat10 * u_xlat3.x;
    u_xlat10 = u_xlat3.x * u_xlat3.x;
    u_xlat17 = u_xlat10 * 0.0208350997 + -0.0851330012;
    u_xlat17 = u_xlat10 * u_xlat17 + 0.180141002;
    u_xlat17 = u_xlat10 * u_xlat17 + -0.330299497;
    u_xlat10 = u_xlat10 * u_xlat17 + 0.999866009;
    u_xlat17 = u_xlat10 * u_xlat3.x;
    u_xlatb24 = abs(u_xlat1.y)<abs(u_xlat1.x);
    u_xlat17 = u_xlat17 * -2.0 + 1.57079637;
    u_xlat17 = u_xlatb24 ? u_xlat17 : float(0.0);
    u_xlat3.x = u_xlat3.x * u_xlat10 + u_xlat17;
    u_xlatb10 = u_xlat1.y<(-u_xlat1.y);
    u_xlat10 = u_xlatb10 ? -3.14159274 : float(0.0);
    u_xlat3.x = u_xlat10 + u_xlat3.x;
    u_xlat10 = min(u_xlat1.y, u_xlat1.x);
    u_xlat1.x = max(u_xlat1.y, u_xlat1.x);
    u_xlatb8 = u_xlat10<(-u_xlat10);
    u_xlatb1 = u_xlat1.x>=(-u_xlat1.x);
    u_xlatb1 = u_xlatb1 && u_xlatb8;
    u_xlat1.x = (u_xlatb1) ? (-u_xlat3.x) : u_xlat3.x;
    u_xlat1.x = u_xlat1.x + 6.28000021;
    u_xlat1.x = u_xlat1.x * 0.159235656;
    u_xlatb8 = u_xlat1.x>=(-u_xlat1.x);
    u_xlat1.x = fract(u_xlat1.x);
    u_xlat1.x = (u_xlatb8) ? u_xlat1.x : (-u_xlat1.x);
    u_xlat1.x = u_xlat1.x * 0.99999994;
    u_xlat1.x = (u_xlatb2.y) ? u_xlat1.x : u_xlat15.x;
    u_xlat1.x = (u_xlatb2.x) ? u_xlat22 : u_xlat1.x;
    u_xlat1.x = (int(_type) != 0) ? u_xlat1.x : u_xlat15.x;
    u_xlat1.x = clamp(u_xlat1.x, 0.0, 1.0);
    u_xlat8.xyz = _color1.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat8.xyz = _color1.xyz * u_xlat8.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat3.xyz = u_xlat8.xyz * _color1.xyz;
    u_xlat8.xyz = _color2.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat8.xyz = _color2.xyz * u_xlat8.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat3.w = _color1.w;
    u_xlat4.xyz = _color2.xyz * u_xlat8.xyz + (-u_xlat3.xyz);
    u_xlat4.w = (-u_xlat3.w) + _color2.w;
    u_xlat1 = u_xlat1.xxxx * u_xlat4 + u_xlat3;
    u_xlat2.xy = acScreenNorm.xy * _resolution.xy;
    u_xlat2.x = dot(u_xlat2.xy, vec2(0.0671105608, 0.00583714992));
    u_xlat2.x = fract(u_xlat2.x);
    u_xlat2.x = u_xlat2.x * 52.9829178;
    u_xlat2.x = fract(u_xlat2.x);
    u_xlat2.x = u_xlat2.x * 0.00392156886 + -0.00196078443;
    u_xlat1 = u_xlat1 + u_xlat2.xxxx;
    u_xlat3.xyz = u_xlat0.xyz / u_xlat0.www;
    u_xlat4.xyz = u_xlat1.xyz * u_xlat3.xyz;
    u_xlat4.w = 1.0;
    u_xlat4 = u_xlat0.wwww * u_xlat4;
    u_xlat5.xyz = u_xlat0.xyz + u_xlat1.xyz;
    u_xlatb2.x = int(_blend_mode)==3;
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat6.xyz = (-u_xlat1.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat3.xyz = (-u_xlat3.xyz) * u_xlat6.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat3.w = 1.0;
    u_xlat3 = u_xlat0.wwww * u_xlat3;
    u_xlat6.xyz = u_xlat1.xyz;
    u_xlat6.w = 1.0;
    u_xlat6 = u_xlat0.wwww * u_xlat6;
    u_xlat3 = (u_xlatb2.x) ? u_xlat3 : u_xlat6;
    u_xlat5.w = u_xlat0.w;
    u_xlat3 = (u_xlatb2.w) ? u_xlat5 : u_xlat3;
    u_xlat2 = (u_xlatb2.z) ? u_xlat4 : u_xlat3;
    u_xlat1.x = u_xlat1.w * _blend;
    u_xlat2 = (-u_xlat0) + u_xlat2;
    u_xlat1 = u_xlat1.xxxx * u_xlat2 + u_xlat0;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
